import os, requests
base=os.environ['GALAXY_URL'].rstrip('/')
key=open(os.environ['GALAXY_API_KEY_FILE']).read().strip()
h={'x-api-key':key}
for ep in ['/api/datasets/f9cad7b01a47213520b505ec70270543','/api/histories/bbd44e69cb8906b5649e06e9a2df3818/contents/f9cad7b01a47213520b505ec70270543']:
 d=requests.get(base+ep,headers=h,timeout=30).json();print(ep)
 for k in ['state','visible','name','misc_info','peek','deleted','purged']: print(k, str(d.get(k))[:5000])
PY"

